#!/usr/bin/env python3
"""
Loader
v25.5.03 - Made by Monkeyheheh
Loader is designed to secure your code so only people with the key can run the code.
The code that is ran is ENCRYPTED_BLOB, paste your encrypted string there and whenever you enter the correct key you're in your system.
(Make sure to use argon2 and aes-256 for absolute security and compatibility)
"""

from __future__ import annotations

import gc
import os
import stat
import sys
import subprocess
import tempfile
import traceback
from getpass import getpass
from pathlib import Path
from typing import Any, Dict, List, Optional

# ---------------------------------------------------------------------------
# Project crypto
# ---------------------------------------------------------------------------
try:
    from utils.template import decrypt_data, DecryptionError
except ImportError:
    try:
        from template import decrypt_data, DecryptionError
    except ImportError as e:
        sys.stderr.write("Cannot import decrypt_data / DecryptionError.\n")
        sys.stderr.write(f"{e}\n")
        sys.exit(1)

# ===========================================================================
# PASTE CIPHERTEXT HERE
# ===========================================================================
ENCRYPTED_BLOB = r"""

""".strip()

# Must match your encrypt_data(...) call exactly
AAD: Optional[bytes] = None  # e.g. b"oblivx-loader-v1"
TIME_COST = 3
MEMORY_COST = 65536
PARALLELISM = 4

# ---------------------------------------------------------------------------
# How to run the decrypted payload
#
# MODE = "python"
#   Payload is Python source. Executed fully in memory (no file on disk).
#
# MODE = "stdin"
#   Pipe decrypted bytes to an interpreter on stdin (often no script file).
#   RUN = ["bash"] | ["python3"] | ["node"] | ["ruby"] | ...
#
# MODE = "file"
#   Write payload to a secure temp/memfd path, then run RUN with {path}.
#   RUN = ["python3", "{path}"]
#        ["node", "{path}"]
#        ["bash", "{path}"]
#        ["{path}"]            # binary / script with shebang; needs +x
#        ["cmd", "/c", "{path}"]
# ---------------------------------------------------------------------------
MODE = "python"  # "python" | "stdin" | "file"
RUN: List[str] = ["{path}"]  # used by "stdin" (no {path}) or "file"


def _die(msg: str, code: int = 1) -> None:
    sys.stderr.write(msg + "\n")
    sys.exit(code)


def _blob() -> str:
    raw = ENCRYPTED_BLOB.strip()
    if not raw or raw == "PASTE_ENCRYPTED_BASE64_HERE":
        _die("ENCRYPTED_BLOB is empty — paste your ciphertext into loader.py")
    return "".join(raw.split())


def _decrypt(password: str) -> bytes:
    return decrypt_data(
        _blob(),
        password,
        aad=AAD,
        time_cost=TIME_COST,
        memory_cost=MEMORY_COST,
        parallelism=PARALLELISM,
    )


# ----- secure ephemeral file (prefer memfd on Linux) ---------------------

def _memfd(data: bytes, name: str = "payload") -> Optional[Path]:
    """Anonymous in-memory file via memfd_create (Linux). Returns path or None."""
    try:
        import ctypes
        import ctypes.util

        libc = ctypes.CDLL(ctypes.util.find_library("c") or "libc.so.6", use_errno=True)
        MFD_CLOEXEC = 1
        memfd_create = libc.memfd_create
        memfd_create.argtypes = [ctypes.c_char_p, ctypes.c_uint]
        memfd_create.restype = ctypes.c_int

        fd = memfd_create(name.encode("utf-8"), MFD_CLOEXEC)
        if fd < 0:
            return None
        os.write(fd, data)
        os.lseek(fd, 0, os.SEEK_SET)
        # Keep fd open for the lifetime of the path use; caller must os.close(fd)
        path = Path(f"/proc/self/fd/{fd}")
        path._oblivx_fd = fd  # type: ignore[attr-defined]
        return path
    except Exception:
        return None


def _secure_temp(data: bytes, executable: bool) -> Path:
    """
    Create a temp file with restrictive perms, write data, return path.
    Caller must wipe + delete in a finally block.
    """
    flags = os.O_RDWR | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW

    fd = None
    path = None
    try:
        fd = os.open(
            tempfile.mktemp(prefix="oblivx_", dir=tempfile.gettempdir()),
            flags,
            0o600,
        )
        path = Path(f"/proc/self/fd/{fd}") if sys.platform == "linux" else None
        # Prefer real path for portability when not using /proc
        # mktemp+O_EXCL above is racy for name; use mkstemp instead
    except Exception:
        pass
    finally:
        if fd is not None:
            try:
                os.close(fd)
            except Exception:
                pass

    # Portable path: mkstemp
    fd, name = tempfile.mkstemp(prefix="oblivx_", suffix=".bin")
    p = Path(name)
    try:
        os.write(fd, data)
        os.fsync(fd)
    finally:
        os.close(fd)

    mode = 0o700 if executable else 0o600
    os.chmod(p, mode)
    return p


def _wipe_and_unlink(path: Path) -> None:
    """Best-effort overwrite + unlink (not guaranteed on all FS / SSDs)."""
    fd = getattr(path, "_oblivx_fd", None)
    if fd is not None:
        try:
            os.close(fd)
        except Exception:
            pass
        return

    try:
        if path.is_file():
            size = path.stat().st_size
            with open(path, "r+b", buffering=0) as f:
                # single pass zero — best-effort only
                f.write(b"\x00" * size)
                f.flush()
                try:
                    os.fsync(f.fileno())
                except Exception:
                    pass
            path.unlink(missing_ok=True)
    except Exception:
        try:
            path.unlink(missing_ok=True)
        except Exception:
            pass


def _run_python(source: bytes) -> None:
    try:
        text = source.decode("utf-8")
    except UnicodeDecodeError:
        _die("Payload is not valid UTF-8 Python source (MODE=python)")

    code = compile(text, "<encrypted_payload>", "exec")
    del text
    g: Dict[str, Any] = {
        "__name__": "__main__",
        "__file__": "<encrypted_payload>",
        "__package__": None,
        "__builtins__": __builtins__,
    }
    exec(code, g, g)


def _run_stdin(data: bytes) -> int:
    if not RUN:
        _die('MODE="stdin" requires RUN, e.g. RUN = ["bash"] or ["node"]')
    try:
        r = subprocess.run(
            RUN,
            input=data,
            check=False,
        )
        return int(r.returncode)
    except FileNotFoundError:
        _die(f"Interpreter not found: {RUN[0]}")
    except Exception as e:
        _die(f"Failed to run payload on stdin: {e}")


def _run_file(data: bytes) -> int:
    if not RUN:
        _die('MODE="file" requires RUN, e.g. RUN = ["bash", "{path}"] or ["{path}"]')

    executable = any(part == "{path}" for part in RUN) and (
        RUN[0] == "{path}" or RUN == ["{path}"]
    )

    path: Optional[Path] = None
    # Prefer memfd on Linux when executing by path
    if sys.platform.startswith("linux"):
        path = _memfd(data)
        if path is not None and executable:
            # memfd path needs execute via /proc/self/fd/N — works if mounted
            try:
                os.chmod(path, 0o700)
            except Exception:
                pass

    if path is None:
        path = _secure_temp(data, executable=executable or ("{path}" in RUN))

    cmd = [path.as_posix() if a == "{path}" else a for a in RUN]

    try:
        # Detach cwd secrets: run as-is in current cwd (user choice)
        r = subprocess.run(cmd, check=False)
        return int(r.returncode)
    except FileNotFoundError:
        _die(f"Cannot execute: {cmd[0]}")
    except PermissionError:
        _die(f"Permission denied executing: {cmd[0]}")
    except Exception as e:
        _die(f"Failed to run payload file: {e}")
    finally:
        _wipe_and_unlink(path)


def main() -> None:
    mode = MODE.strip().lower()
    if mode not in {"python", "stdin", "file"}:
        _die('MODE must be "python", "stdin", or "file"')

    try:
        password = getpass("Password: ")
    except (KeyboardInterrupt, EOFError):
        sys.stderr.write("\n")
        _die("Cancelled.", 130)

    if not password:
        _die("Empty password.")

    data: Optional[bytes] = None
    try:
        try:
            data = _decrypt(password)
        except DecryptionError:
            _die("Wrong password or corrupted blob.")
        except Exception:
            _die("Wrong password or corrupted blob.")
    finally:
        password = None  # type: ignore
        del password
        gc.collect()

    assert data is not None
    rc = 0
    try:
        if mode == "python":
            _run_python(data)
        elif mode == "stdin":
            rc = _run_stdin(data)
        else:
            rc = _run_file(data)
    except SystemExit as e:
        code = e.code
        if code is None:
            raise SystemExit(0)
        raise
    except Exception:
        sys.stderr.write("Payload failed after successful decrypt:\n")
        traceback.print_exc()
        _die("Exit due to payload error.", 1)
    finally:
        del data
        gc.collect()

    if rc != 0:
        sys.exit(rc)


if __name__ == "__main__":
    main()
